# Re-enable Diagnostic Data Collection Write-Host "Re-enabling diagnostic data collection..." -ForegroundColor Cyan # Set diagnostic data to basic (level 1) Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection" -Name "AllowTelemetry" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "AllowTelemetry" -ErrorAction SilentlyContinue # Re-enable Diagnostic Policy Service Set-Service -Name "DPS" -StartupType Automatic -ErrorAction SilentlyContinue Start-Service -Name "DPS" -ErrorAction SilentlyContinue Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "DoNotShowFeedbackNotifications" -ErrorAction SilentlyContinue Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Error Reporting" -Name "Disabled" -ErrorAction SilentlyContinue Write-Host "Diagnostic data collection has been re-enabled (basic level)." -ForegroundColor Green